        self.paging_flag = matches.value_of("paging").map(|value| value.to_string());
        self.extra_plain = matches.occurrences_of("plain") > 1;
        self.no_paging_set = matches.is_present("no-paging");
        self.pager_spec = matches.value_of("pager").map(|value| value.to_string());
    }
}

fn capture_stdin_presence(&mut self, inputs: &[Input]) {
    self.stdin_present = inputs.iter().any(Input::is_stdin);
}

fn paging_from_always(&mut self) {
    self.paging_mode = PagingMode::Always;
}

fn paging_from_never(&mut self) {
    self.paging_mode = PagingMode::Never;
}

fn paging_from_auto_plain_or_flag(&mut self) -> bool {
    if self.extra_plain || self.no_paging_set {
        self.paging_mode = PagingMode::Never;
        true
    } else {
        false
    }
}

fn paging_from_auto_stdin(&mut self) {
    if self.paging_interactive && !atty::is(Stream::Stdin) {
        self.paging_mode = PagingMode::QuitIfOneScreen;
    } else {
        self.paging_mode = PagingMode::Never;
    }
}

fn paging_from_auto_files(&mut self) {
    if self.paging_interactive {
        self.paging_mode = PagingMode::QuitIfOneScreen;
    } else {
        self.paging_mode = PagingMode::Never;
    }
}

fn resolve_paging_mode(&mut self, inputs: &[Input]) {
    self.capture_paging_flags();
    self.capture_stdin_presence(inputs);
    match self.paging_flag.as_deref() {
        Some("always") => {
            self.paging_from_always();
            self.paging_mode = PagingMode::Always;
        }
        Some("never") => {
            self.paging_from_never();
            self.paging_mode = PagingMode::Never;
        }
        Some("auto") | None => {
            if self.extra_plain || self.no_paging_set {
                let _ = self.paging_from_auto_plain_or_flag();
                self.paging_mode = PagingMode::Never;
            } else if self.stdin_present {
                self.paging_from_auto_stdin();
            } else {
                self.paging_from_auto_files();
            }
        }
        _ => unreachable!("other values for --paging are not allowed"),
    }
}

fn pager_spec_or_env(&self) -> Option<String> {
    if let Some(spec) = self.pager_spec.clone() {
        if spec.trim().is_empty() {
            None
        } else {
            Some(spec)
        }
    } else {
        None
    }
}

fn pager_executable_name(&self) -> String {
    let spec = if let Some(spec) = self.pager_spec.clone() {
        if spec.trim().is_empty() {
            None
        } else {
            Some(spec)
        }
    } else {
        self.pager_spec_or_env()
    };
    get_pager_executable(spec.as_deref()).unwrap_or_else(|| "less".to_owned())
}

fn paging_mode_value(&self) -> PagingMode {
    self.paging_mode
}

fn capture_style_flags(&mut self) {
    self.style_flags.clear();
    if let Some(matches) = self.matches.as_ref() {
        self.decorations_never = matches.value_of("decorations") == Some("never");
        self.number_set = matches.is_present("number");
        self.plain_set = matches.is_present("plain");
        if let Some(styles) = matches.value_of("style") {
            self.style_flags = styles
                .split(',')
                .filter(|item| !item.is_empty())
                .map(|item| item.to_string())
                .collect();
        }
    }
}

fn style_when_decorations_never(&mut self) {
    self.style_set = StyleComponents(HashSet::new());
}

fn style_when_number(&mut self) {
    self.style_set = StyleComponents([StyleComponent::LineNumbers].iter().cloned().collect());
}

fn style_when_plain(&mut self) {
    self.style_set = StyleComponents([StyleComponent::Plain].iter().cloned().collect());
}

fn style_from_env_var(&self) -> Result<Option<Vec<StyleComponent>>> {
    let parsed = env::var("BAT_STYLE")
        .ok()
        .map(|style_str| {
            style_str
                .split(',')
                .map(StyleComponent::from_str)
                .collect::<Result<Vec<StyleComponent>>>()
        })
        .transpose()?;
    if parsed.is_none() && !self.style_flags.is_empty() {
        Ok(None)
    } else {
        Ok(parsed)
    }
}

fn style_from_captured_flags(&self) -> Vec<StyleComponent> {
    self.style_flags
        .iter()
        .map(|style| style.parse::<StyleComponent>())

