use atty::{self, Stream};

use crate::clap_app::CliEngine;
use clap::ArgMatches;

use bat::{config::Config, error::*, input::Input};

pub struct App {
    pub matches: ArgMatches<'static>,
    interactive_output: bool,
}

impl App {
    pub fn new() -> Result<Self> {
        #[cfg(windows)]
        let _ = ansi_term::enable_ansi_support();

        let interactive_output = atty::is(Stream::Stdout);
        let mut engine = CliEngine::new(interactive_output);

        Ok(App {
            matches: engine.parse_matches()?,
            interactive_output,
        })
    }

    pub fn config(&self, inputs: &[Input]) -> Result<Config> {
        let mut engine = CliEngine::from_matches(self.matches.clone(), self.interactive_output);
        engine.build_config(&self.matches, inputs)
    }

    pub fn inputs(&self) -> Result<Vec<Input>> {
        let mut engine = CliEngine::from_matches(self.matches.clone(), self.interactive_output);
        engine.build_inputs(&self.matches)
    }

    pub fn execute(&self) -> Result<bool> {
        let mut engine = CliEngine::from_matches(self.matches.clone(), self.interactive_output);
        engine.execute(&self.matches)
    }

    pub fn run_cache_subcommand(&self, matches: &ArgMatches) -> Result<()> {
        let engine = CliEngine::from_matches(self.matches.clone(), self.interactive_output);
        engine.run_cache_subcommand(matches)
    }

    pub fn print_diagnostics(&self) {
        let engine = CliEngine::from_matches(self.matches.clone(), self.interactive_output);
        engine.emit_diagnostics();
    }

    pub fn run_named_file(&self, name: &str) -> Result<bool> {
        let mut engine = CliEngine::from_matches(self.matches.clone(), self.interactive_output);
        let inputs = vec![Input::ordinary_file(name)];
        let config = engine.build_config(&self.matches, &inputs)?;
        engine.run_controller(inputs, &config)
    }
}

